CREATE TABLE IF NOT EXISTS branches(id integer PRIMARY KEY, name text NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS users(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, username text UNIQUE NOT NULL, name text NOT NULL, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('teller','supervisor')), branch_id integer NOT NULL REFERENCES branches(id));
CREATE TABLE IF NOT EXISTS sessions(token_hash text PRIMARY KEY, user_id bigint NOT NULL REFERENCES users(id), expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS members(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, nik text UNIQUE NOT NULL CHECK(nik ~ '^[0-9]{16}$'), name text NOT NULL, phone text NOT NULL, address text NOT NULL, home_branch_id integer NOT NULL REFERENCES branches(id), balance bigint NOT NULL DEFAULT 0 CHECK(balance>=0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS transactions(id text PRIMARY KEY, member_id bigint NOT NULL REFERENCES members(id), branch_id integer NOT NULL REFERENCES branches(id), actor_id bigint NOT NULL REFERENCES users(id), kind text NOT NULL CHECK(kind IN ('deposit','withdrawal')), amount bigint NOT NULL CHECK(amount>0), note text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS journal_lines(transaction_id text NOT NULL REFERENCES transactions(id), line_no integer NOT NULL, account text NOT NULL CHECK(account IN ('cash','member_savings')), debit bigint NOT NULL DEFAULT 0 CHECK(debit>=0), credit bigint NOT NULL DEFAULT 0 CHECK(credit>=0), PRIMARY KEY(transaction_id,line_no), CHECK((debit>0 AND credit=0) OR (credit>0 AND debit=0)));
CREATE TABLE IF NOT EXISTS loans(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, member_id bigint NOT NULL REFERENCES members(id), receiving_branch_id integer NOT NULL REFERENCES branches(id), responsible_branch_id integer NOT NULL REFERENCES branches(id), created_by bigint NOT NULL REFERENCES users(id), amount bigint NOT NULL CHECK(amount>0), tenor_months integer NOT NULL CHECK(tenor_months BETWEEN 1 AND 120), purpose text NOT NULL, product text NOT NULL DEFAULT 'regular' CHECK(product='regular'), risk text NOT NULL CHECK(risk IN ('low','medium','high')), status text NOT NULL DEFAULT 'submitted' CHECK(status IN ('submitted','approved','rejected')), decision_by bigint REFERENCES users(id), decision_reason text, authority_limit bigint, decided_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS requests(user_id bigint NOT NULL REFERENCES users(id), request_key text NOT NULL, fingerprint text NOT NULL, response jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,request_key));
CREATE TABLE IF NOT EXISTS audit_events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, actor_id bigint NOT NULL REFERENCES users(id), action text NOT NULL, entity_id text NOT NULL, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS transactions_member_idx ON transactions(member_id,created_at DESC);
CREATE INDEX IF NOT EXISTS loans_member_idx ON loans(member_id);
